def solve(items):
    a = list(items)
    for i in range(1, len(a)):
        key = a[i]
        j = i - 1
        while j >= 0 and a[j][0] > key[0]:
            a[j + 1] = a[j]
            j -= 1
        a[j + 1] = key
    return a

def solve(items):
    if len(items) <= 1:
        return list(items)
    m = len(items)//2
    left, right = solve(items[:m]), solve(items[m:])
    out=[]; i=j=0
    while i<len(left) and j<len(right):
        if left[i][0] <= right[j][0]:
            out.append(left[i]); i+=1
        else:
            out.append(right[j]); j+=1
    return out + left[i:] + right[j:]

from collections import deque
def solve(graph, start):
    q=deque([start]); dist={start:0}
    while q:
        u=q.popleft()
        for v in graph.get(u, []):
            if v not in dist:
                dist[v]=dist[u]+1
                q.append(v)
    return dist

def solve(graph, start):
    seen=set()
    def dfs(u):
        if u in seen:
            return
        seen.add(u)
        for v in graph.get(u, []):
            dfs(v)
    dfs(start)
    return sorted(seen)
